    # Sort applicants by score descending, then by registration number ascending
    sorted_applicants = sorted(applicants, key=lambda x: (-x[1], x[0]))

    # Calculate the interview score cutoff: 150% of m, rounded down
    num_qualifiers = int(m * 1.5)

    # If num_qualifiers is greater than n, then all applicants qualify
    if num_qualifiers >= n:
        cutoff_score = sorted_applicants[-1][1] if sorted_applicants else 0
        qualified = sorted_applicants
    else:
        cutoff_score = sorted_applicants[num_qualifiers - 1][1]
        qualified = [a for a in sorted_applicants if a[1] >= cutoff_score]

    return (cutoff_score, qualified)

