    # Check if lengths of encoded and original are the same
    if len(encoded) != len(original):
        return "Failed"

    # Build the mapping from encoded letter to original letter
    mapping = {}
    for enc, orig in zip(encoded, original):
        if enc in mapping:
            if mapping[enc] != orig:
                return "Failed"
        else:
            mapping[enc] = orig

    # Check that the mapping is a valid substitution cipher
    # Each original letter should map to a unique encoded letter (bijection)
    reverse_mapping = {}
    for orig, enc in zip(original, encoded):
        if orig in reverse_mapping:
            if reverse_mapping[orig] != enc:
                return "Failed"
        else:
            reverse_mapping[orig] = enc

    # Check that all keys in mapping and reverse_mapping are consistent
    # The set of keys in mapping should equal the set of values in reverse_mapping and vice versa
    if set(mapping.keys()) != set(reverse_mapping.values()):
        return "Failed"
    if set(mapping.values()) != set(reverse_mapping.keys()):
        return "Failed"

    # Now decode the message
    result = []
    for char in message:
        if char not in mapping:
            return "Failed"
        result.append(mapping[char])

    return ''.join(result)

